"""Strict format N-Queens harness with board validation and output enforcement."""

import re
from harness_evolve.llm import llm_acall
from typing import Tuple, List


# Strict output format system prompt
SYSTEM_PROMPT = (
    """N-QUEENS BOARD COMPLETION TASK

You are solving an N-Queens chess puzzle. Place all queens on empty rows such that no two queens attack each other.

BOARD FORMAT RULES:
- Board is printed with Q for queens, _ for empty cells
- Each row contains cells separated by single spaces: "_ Q _ Q ..."
- Output a COMPLETE board with all n queens placed

CRITICAL OUTPUT FORMAT:
1. Your output MUST contain only ONE <answer>...</answer> block
2. INSIDE the <answer> tag, output ONLY the board (lines of _ and Q, space-separated)
3. NO reasoning, NO explanation, NO text BEFORE or AFTER the <answer> tag
4. NO text INSIDE the <answer> tag except the board itself

EXAMPLE CORRECT OUTPUT:
<answer>
_ _ _ Q _ _ _ _
_ Q _ _ _ _ _ Q
_ _ _ _ _ _ _ Q
Q _ _ _ _ _ _ _
_ _ _ _ _ _ _ Q
_ _ _ _ Q _ _ _
_ Q _ _ _ _ _ _
_ _ _ _ _ Q _ _
</answer>

INPUT BOARD:
GY (input board follows)
"""
)


def extract_board_size_from_question(question: str) -> int:
    """Extract board size from the task question text."""
    # Pattern to match board size description (e.g., "8x8", "8x8 board", "size: 8")
    patterns = [
        r'(\d+)\s*x\s*(\d+)',  # "8x8" format
        r'8\s*x\s*8',  # "8 x 8" format
        r'n\s*queens\s*on\s*(\d+)x?\s*(n|N|\d+)',  # "n queens on 8x8 or n queens on 8"
    ]

    for pattern in patterns:
        match = re.search(pattern, question, re.IGNORECASE)
        if match:
            try:
                return int(match.group(1)) or int(match.group(2))
            except (ValueError, IndexError):
                continue

    # Try counting empty rows if pattern doesn't match
    lines = question.split('\n')
    plain_line_count = 0
    board_strings = []
    for line in lines:
        if '_ ' in line or 'Q ' in line or ' _' in line or ' Q' in line:
            tokens = line.strip().split()
            if len(tokens) >= 3 and all(c in ' _Q' for c in tokens):
                board_strings.append(line.strip())

    if len(board_strings) > 0:
        return len(board_strings)

    # Default to 8 for standard N-Queens
    return 8


def normalize_board(text: str, board_size: int) -> str:
    """Normalize board text to standard format.

    - Strip all whitespace
    - Normalize line endings
    - Remove empty lines
    - Ensure proper spacing between cells
    """
    text = text.strip().replace('\r\n', '\n').replace('\r', '\n')
    lines = [line for line in text.split('\n') if line.strip()]

    if len(lines) != board_size:
        # Return empty (size mismatch)
        return ""

    for i, line in enumerate(lines):
        tokens = line.split()
        if len(tokens) != board_size or not all(c in ' _Q' for c in tokens):
            return ""

    return '\n'.join(lines)


def validate_board(board: str, board_size: int) -> Tuple[bool, dict]:
    """Validate that board satisfies N-Queens constraints.

    Returns:
        (is_valid, trace_info)
    """
    trace_info = {}

    # Check dimensions
    lines = [line.strip() for line in board.split('\n') if line.strip()]
    if len(lines) != board_size:
        return False, {"error": f"Expected {board_size} rows, got {len(lines)}", "format_valid": False}

    # Check each row has exactly one queen
    for i, line in enumerate(lines):
        tokens = line.split()
        if len(tokens) != board_size:
            return False, {"error": f"Row {i}: expected {board_size} columns, got {len(tokens)}", "format_valid": False}

        queens_in_row = sum(1 for c in tokens if c == 'Q')
        if queens_in_row != 1:
            return False, {"error": f"Row {i}: {queens_in_row} queens, expected 1", "format_valid": False}

    # Check column uniqueness
    cols = []
    queens = []
    for i, line in enumerate(lines):
        for j, c in enumerate(line.split()):
            if c == 'Q':
                cols.append(j)
                queens.append((i, j))

    if len(cols) != board_size or len(cols) != len(set(cols)):
        return False, {"error": "Column uniqueness violated", "format_valid": False}

    # Check diagonal constraints (main: row-col=const, anti: row+col=const)
    main_diags = {q[0] - q[1] for q in queens}
    anti_diags = {q[0] + q[1] for q in queens}

    if len(main_diags) != board_size or len(anti_diags) != board_size:
        return False, {"error": "Diagonal constraint violated", "format_valid": False}

    return True, {"format_valid": True, "board_valid": True, "queen_count": board_size}


async def solve(model, question: str, **kwargs) -> dict:
    """Solve N-Queens puzzle with strict format enforcement and validation.

    Returns:
        dict: {"answer": str, "traces": {...}}
    """
    # Determine board size from question or default to 8
    board_size = extract_board_size_from_question(question)
    if board_size:
        board_size = int(board_size)
    else:
        board_size = 8

    # If board_size is 0 (invalid), default to 8
    if board_size <= 0:
        board_size = 8

    # Make LLM call
    content = await llm_acall(
        model=model,
        messages=[
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": question},
        ],
        max_tokens=32768,
        temperature=0.6,  # Calibrated for reasoning tasks
        thinking=kwargs.get("thinking"),
    )

    # Extract answer from <answer> tags
    answer_match = re.search(r'<answer>(.*?)</answer>', content, re.DOTALL | re.IGNORECASE)

    if answer_match:
        extracted_answer = answer_match.group(1).strip()
    else:
        # Fallback: no <answer> tag found, use raw content
        extracted_answer = content.strip()

    # Normalize the extracted answer
    normalized_answer = normalize_board(extracted_answer, board_size)

    # Validate the board
    is_valid, trace_info = validate_board(normalized_answer, board_size)

    if not is_valid:
        # Try fallback: extract from content directly without <answer> tag filtering
        fallback_answer = content
        fallback_match = re.search(r'<answer>(.*?)</answer>(?:</?question>)?', fallback_answer, re.DOTALL)
        if fallback_match:
            extracted = fallback_match.group(1).strip()
            normalized = normalize_board(extracted, board_size)
            is_valid, trace_info = validate_board(normalized, board_size)

    # Ensure we always have a valid board in answer
    if not is_valid:
        # Accept whatever the LLM gave us, but warn it won't score
        final_board = normalized_answer if normalized_answer else extracted_answer
    else:
        final_board = normalized_answer

    # Store for traces
    full_content = content[:5000] if len(content) > 5000 else content

    return {
        "answer": final_board,
        "traces": {
            "method": "strict_n_queens_validation",
            "board_size": board_size,
            "original_content": full_content,
            "validation_info": trace_info,
            "extraction_source": "answer_tag" if answer_match else "raw_content"
        }
    }

"""Rubik's cube solving harness with few-shot examples and output validation."""

import re
from harness_evolve.llm import llm_acall

SYSTEM_PROMPT = (
    "You are solving a Rubik's cube puzzle. The user message contains a description of a scrambled cube.\n\n"
    "Your task is to provide a solution sequence using Singmaster notation.\n\n"
    "Valid moves only:\n"
    "- U: One turn Up\n"
    "- D: One turn Down\n"
    "- L: One turn Left\n"
    "- R: One turn Right\n"
    "- F: One turn Front\n"
    "- B: One turn Back\n\n"
    "Format requirements:\n"
    "- Write each move as a single letter (U, D, L, R, F, B)\n"
    "- Do not use U2, D2, L2, R2, F2, B2 for multi-turn moves. Write them as 'U U' or 'U U U'\n"
    "- Do NOT use colors or invalid letters (E, G, A, etc.)\n\n"
    "Format your final answer in the required format as described in the input. Wrap your answer in <answer> tags: <answer>your answer here</answer>\n"
    "Output only the <answer>...</answer> block with the solution sequence.\n"
    "\n"
    "Few-shot example:\n"
    "User: Here's a 3x3 Rubik's cube:\n"
    "          R R R\n"
    "          G G G\n"
    "          B B B\n"
    "          Y Y Y\n"
    "          O O O\n"
    "          Y W G\n"
    "Answer: <answer>U U F F D D R R</answer>\n"
    "\n"
    "Read the input carefully. Provide ONLY the <answer>...</answer> block in your final output.\n"
    "<answer>Your final move sequence in Singmaster notation</answer>"
)

# Validation regex to ensure answer contains only valid move characters
MOVE_REGEX = re.compile(r'^[U D L R F B]+$')

async def solve(model, question, **kwargs):
    """Solve the Rubik's cube with chain-of-thought reasoning and output validation."""
    # Strip any pre-existing <answer> tags and extract only the core sequence for validation
    answer_choice = kwargs.get("answer_choice", None)
    try:
        answer_choice = answer_choice.strip() if answer_choice else ""
    except AttributeError:
        answer_choice = ''

    # Extract and validate the answer sequence
    try:
        if 'contains' in globals():
            found_solutions = False
            for soln in ['U D L R F B']:
                soln = soln.strip()
                found = re.fullmatch(r'[U D L R F B]+', soln)
                if found and found != soln:
                    continue
                found = re.fullmatch(r'[UDLRFB]+', soln)
                if found and found != soln:
                    continue

        # Validate that answer content contains only valid characters
        # Use STRING_CONSTRAINT validation or ANALYSIS workflow as needed
        constraints = kwargs.get("CONSTRAINTS", [])
        for i, c in enumerate(constraints):
            if c:
                constraints[i] = c

        # Validate the answer against the regex
        clean_moves = MOVE_REGEX.match(answer_choice)
        if clean_moves:
            answer_choice = answer_choice.strip()
        else:
            answer_choice = None

    except Exception:
        pass

    try:
        if answer_choice:
            answer_choice = answer_choice.strip()

    except Exception:
        pass

    # Validate the answer string
    try:
        cleaned_moves = answer_choice.strip()
        if cleaned_moves:
            match = re.fullmatch(r'[U D L R F B]+', cleaned_moves)
            if match:
                answer_choice = cleaned_moves
            else:
                return {"answer": "<answer>error_invalid_sequence</answer>", "traces": {"method": "validated_clean"}}
        else:
            return {"answer": "<answer>U U</answer>", "traces": {"method": "default_sequence"}}
    except Exception:
        pass

    # Make the LLM call with chain-of-thought enabled
    content = await llm_acall(
        model=model,
        messages=[
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": question},
        ],
        max_tokens=32768,
        temperature=0.6,
        thinking=kwargs.get("thinking"),
    )

    # Extract the answer from the response, handling various formats
    try:
        answer_text = content.strip()

        # Look for <answer> tags
        if '<answer>' in answer_text:
            # Extract first answer block
            start_idx = answer_text.find('<answer>') + len('<answer>')
            end_idx = answer_text.find('</answer>')
            if end_idx != -1:
                answer_text = answer_text[start_idx:end_idx].strip()

        # If no <answer> found, try to extract the sequence
        answer_text = re.sub(r'<answer>|</answer>', '', answer_text, flags=re.IGNORECASE).strip()

        # Final validation
        if not answer_text:
            return {"answer": "<answer>U U</answer>", "traces": {"method": "default_sequence"}}
        elif not re.fullmatch(r'[UDLRFB]+', answer_text):
            # Return sanitized valid sequence only
            valid_sequence = re.findall(r'[UDLRFB]', answer_text)
            if valid_sequence:
                return {"answer": f"<answer>{''.join(valid_sequence)}</answer>", "traces": {"method": "sanitized"}}
            else:
                return {"answer": "<answer>U U</answer>", "traces": {"method": "sanitized"}}
        else:
            return {"answer": f"<answer>{answer_text}</answer>", "traces": {"method": "validated"}}

    except Exception:
        return {"answer": "<answer>U U</answer>", "traces": {"method": "error"}}

"""Rubik's Cube solver harness with strict validation and retry logic."""

import re
from harness_evolve.llm import llm_acall
from typing import Optional, Tuple
from collections import deque
import asyncio
from typing import Dict, List


SYSTEM_PROMPT = (
    "You are a Rubik's Cube solver expert.\n"
    "Your task is to solve the Rubik's Cube puzzle shown in the grid.\n\n"
    "CRITICAL: Output ONLY the move sequence inside <answer>...</answer> tags.\n"
    "Do NOT explain your reasoning or output any other text outside the tags.\n\n"
    "Valid Move Characters: U, D, L, R, F, B, ' (prime for inverse turns, e.g., F' = F' inverse)\n"
    "Write repeated moves as two letters separated by space: 'U U' not 'U2'.\n"
    "No other characters allowed (like color names: G, Y, W, R, B, etc.)\n"
    "If the cube is already solved, return 'no moves'\n"
    "If the cube is unsolvable, return 'unsolvable'\n\n"
    "Now, analyze the cube below and output the solution:\n"
)


async def solve(model, question, **kwargs) -> dict:
    try:
        max_attempts = 3
        responses: list[str] = []

        # Collect up to max_attempts responses
        for attempt in range(max_attempts):
            response = await llm_acall(
                model=model,
                messages=[
                    {"role": "system", "content": SYSTEM_PROMPT},
                    {"role": "user", "content": question},
                ],
                max_tokens=32768,
                temperature=0.6,
                thinking=kwargs.get("thinking", False),
            )
            responses.append(response)

        # Extract and validate
        final_answer: Optional[str] = None
        trace_list: List[Dict] = []

        for idx, res in enumerate(responses):
            match = re.search(r'<answer>(.*?)</answer>', res, re.DOTALL)
            if match:
                extracted = match.group(1).strip().lower()
                trace_list.append({
                    "attempt": idx,
                    "full_content": res,
                    "extracted_answer": extracted
                })

                # Special answers are valid
                if extracted in ("no moves", "unsolvable"):
                    final_answer = extracted
                    break
                # Valid character check
                valid_chars = set("u d l r f b ' 2 \t\n")
                if all(c in valid_chars for c in extracted):
                    final_answer = extracted
                    break

        if final_answer is None:
            final_answer = "no moves"

        # Reject invalid answers that have non-standard characters
        if not final_answer:
            return {
                "answer": "unsolvable",
                "traces": {
                    "method": "strict_validation_harness",
                    "error": "No valid answer found in attempts"
                }
            }

        return {
            "answer": final_answer,
            "traces": {
                "method": "strict_validation_harness",
                "attempts": len(responses),
                "response_count": {
