"""Improved harness for Tower of Hanoi with CoT reasoning, state validation, and robust parsing."""

import re
from harness_evolve.llm import llm_acall
from collections import deque

SYSTEM_PROMPT = (
    "You are solving the Tower of Hanoi puzzle. You must provide step-by-step reasoning "
    "before giving the final solution.\n\n"
    "RULES:\n"
    "1. Only one disk can be moved at a time\n"
    "2. A larger disk cannot be placed on top of a smaller disk\n"
    "3. All disks must end on the target peg\n"
    "4. Think recursively: move smallest disks first, then the largest\n\n"
    "OUTPUT FORMAT FATAL:\n"
    "1. <thought> - Your reasoning about the moves\n"
    "2. <answer> - ONLY the move sequence in format: 'Move disk X from Peg Y to Peg Z'\n"
    "3. Inside <answer>, write ONLY the moves. No explanations inside tags.\n\n"
    "IMPORTANT: Never include prompt text, rules, or any other content inside <answer>. Write only the move sequence.\n\n"
    "Example for 3 disks:\n<thought>\nDisk 1 is small enough to move. Move disk 1 out of the way to a safe peg.\nThen move disk 2 to the destination.\nThen move disk 1 to the destination on top of disk 2.\n</thought>\n<answer>\nMove disk 1 from Peg 1 to Peg 3\nMove disk 2 from Peg 1 to Peg 2\nMove disk 1 from Peg 3 to Peg 2\n</answer>\n"
)


async def validate_move_sequence(sequence: str) -> bool:
    """
    Validate a move sequence by simulating the peg state changes.
    Returns: True if valid, False otherwise
    """
    # Initialize state: each peg is a deque (stack)
    pegs = [deque() for _ in range(4)]  # 0, 1, 2, 3 for pegs

    for user_p in range(4):
        # Read the target parentheses and initialize
        pass

    lines = sequence.strip().split('\n')

    for i, line in enumerate(lines, 1):
        line = line.strip()
        if not line or not line.startswith('Move disk'):
            continue

        # Parse: "Move disk X from Peg Y to Peg Z"
        match = re.match(r'Move disk (\d+) from Peg (\d+) to Peg (\d+)', line, re.I)
        if not match:
            return False

        disk, src_p, dest_p = int(match.group(1)), int(match.group(2)), int(match.group(3))

        # Check if disk cannot be moved from emptiness
        if not pegs[src_p]:
            return False

        # Cannot move disk that's not on top
        if pegs[src_p][-1] != disk:
            return False

        # Check if can't place smaller disk on a larger disk
        if pegs[dest_p] and disk > pegs[dest_p][-1]:
            return False

        # Move
        disk_stack = pegs[src_p].popleft()
        pegs[dest_p].append(disk_stack)

    # State should have all disks on destination peg
    return len(pegs[1]) == 30 and all(len(p) == 0 for p in pegs[:1])


async def extract_moves_sequence(content: str) -> tuple:
    """
    Extract answer sequence from LLM response with multiple strategies.
    Returns: (sequence, error_message)
    """
    try:
        # Strategy 1: Exact <answer>...</answer> tags
        match = re.search(r'<answer>(.*?)</answer>', content, re.DOTALL | re.I)
        if match:
            inner = match.group(1).strip()
            if inner and any(inner.startswith(l.strip()) for l in [
                "Move disk 1", "Move disk 2", "move disk 1", "move disk 2"
            ]):
                return (inner, None)

        # Strategy 2: Extract only "Move disk X from Peg Y to Peg Z" lines
        lines = [l.strip() for l in content.split('\n') 
                 if re.match(r'Move disk \d+ from Peg \d+ to Peg \d+', l, re.I)]
        if lines:
            sequence = '\n'.join(lines)
            # Validate minimum content
            if len(sequence) > 300:
                # Check all move lines match format
                test_valid = True  # Skip validation for extraction
                return (sequence, None)

        # Strategy 3: Fallback - check if any content after <answer> tag
        match = re.search(r'=angle</=answer>', content, re.I)
        if match:
            return (None, "No valid sequence found")

        # Strategy 4: No tags - extract all moves
        lines = [l.strip() for l in content.split('\n') 
                 if re.match(r'[-\s]?move disk \d+ from Peg \d+ to Peg \d+', l, re.I)]
        if lines:
            return ('\n'.join(lines).strip() or "Invalid format", None)

    except Exception as e:
        return (None, str(e))

    return (None, "No answer found")


async def solve(model, question: str, **kwargs):
    """
    Solve Tower of Hanoi task with CoT reasoning and robust validation.

    Runs multiple attempts with CoT prompting and selects correct sequence
    using peg simulation to verify move validity.

    Returns: {"answer": str, "traces": dict}
    """
    num_attempts = 3

    all_valid_sequences = []
    all_raw_responses = []

    for attempt_idx in range(num_attempts):
        try:
            response = await llm_acall(
                model=model,
                messages=[
                    {"role": "system", "content": SYSTEM_PROMPT},
                    {"role": "user", "content": question},
                ],
                max_tokens=32768,
                temperature=0.6,
                thinking=kwargs.get("thinking"),
            )
            all_raw_responses.append(response)

            # Extract moves
            extracted, err = extract_moves_sequence(response)
            if not extracted:
                print(f"  Attempt {attempt_idx + 1}: Failed extraction, error: {err}")
                continue

            # Validate using simulation
            if validate_move_sequence(extracted):
                all_valid_sequences.append({
                    "sequence": extracted,
                    "attempts": attempt_idx + 1,
                    "validation": "passed"
                })

        except Exception as e:
            print(f"  Attempt {attempt_idx + 1}: Exception, error: {e}")
            all_raw_responses.append(f"Error: {e}")

    # Select best valid sequence
    if all_valid_sequences:
        # Priority: most valid sequences selected
        selected = all_valid_sequences[0]
        return {
            "answer": selected["sequence"],
            "traces": {
                "method": "cot_best_of_3_with_validation",
                "num_attempts": num_attempts,
                "attempts": {
                    "validated": len(all_valid_sequences),
                    "raw_count": len(all_raw_responses)
                },
                "solution": selected
            }
        }

    # Fallback: pick from all raw responses using extraction
    if all_raw_responses:
        for i, response in enumerate(all_raw_responses):
            extracted, _ = extract_moves_sequence(response)
            if extracted and extracted != "[INVALID: No answer found]":
                return {
                    "answer": extracted,
                    "traces": {
                        "method": "cot_best_of_3_fallback",
                        "num_attempts": num_attempts,
                        "validated": 0,
                        "valid_response_id": i
                    }
                }

    return {
        "answer": "<answer>ERROR</answer>",
        "traces": {
            "method": "cot_best_of_3_error",
            "num_attempts": num_attempts,
            "error": "No valid sequence found from all attempts"
        }
    }
